[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <!-- Primary Meta Tags -->
  <title>GlobalStone — Global Commercial Real Estate Services</title>
  <meta name="title" content="GlobalStone — Global Commercial Real Estate Services">
  <meta name="description" content="GlobalStone is the global leader in commercial real estate services and investments, providing integrated, data-led solutions across every dimension of real estate. Explore services, insights, and investment opportunities.">

  <!-- Canonical URL -->
  <link rel="canonical" href="https://www.globalstone.com/">

  <!-- Open Graph -->
  <meta property="og:type" content="website">
  <meta property="og:url" content="https://www.globalstone.com/">
  <meta property="og:title" content="GlobalStone — Global Commercial Real Estate Services">
  <meta property="og:description" content="GlobalStone is the global leader in commercial real estate services and investments, providing integrated, data-led solutions across every dimension of real estate.">
  <meta property="og:image" content="https://www.globalstone.com/og-image.jpg">

  <!-- Twitter -->
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://www.globalstone.com/">
  <meta property="twitter:title" content="GlobalStone — Global Commercial Real Estate Services">
  <meta property="twitter:description" content="GlobalStone is the global leader in commercial real estate services and investments, providing integrated, data-led solutions across every dimension of real estate.">
  <meta property="twitter:image" content="https://www.globalstone.com/og-image.jpg">

  <!-- Favicons -->
  <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%23003F2D'/><text x='50' y='68' font-size='52' text-anchor='middle' fill='%23C8A84E' font-family='serif' font-weight='bold'>G</text></svg>">

  <!-- Google Fonts -->
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap" rel="stylesheet">

  <!-- Structured Data -->
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "Organization",
    "name": "GlobalStone",
    "description": "GlobalStone is the global leader in commercial real estate services and investments, providing integrated, data-led solutions across every dimension of real estate.",
    "@id": "https://www.globalstone.com/#organization",
    "url": "https://www.globalstone.com",
    "logo": "https://www.globalstone.com/logo.png",
    "image": "https://www.globalstone.com/og-image.jpg",
    "sameAs": [
      "https://www.linkedin.com/company/globalstone",
      "https://twitter.com/globalstone"
    ]
  }
  </script>

  <style>
    /* === Reset & Base === */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: #1a1a1a;
      background: #fff;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    h1, h2, h3, h4, .serif { font-family: 'Playfair Display', Georgia, serif; }
    a { text-decoration: none; color: inherit; }
    ul { list-style: none; }
    img { max-width: 100%; display: block; }

    /* === Colors === */
    :root {
      --green: #003F2D;
      --teal: #012A2D;
      --gold: #C8A84E;
      --gray-light: #E6E6E6;
      --gray-mid: #8a8a8a;
      --gray-dark: #4a4a4a;
      --white: #ffffff;
      --off-white: #f7f7f5;
      --navy-bg: #0a1628;
    }

    /* === Utility === */
    .container { max-width: 1280px; margin: 0 auto; padding: 0 40px; }
    .section { padding: 90px 0; }
    .section-label {
      font-size: 0.75rem;
      text-transform: uppercase;
      letter-spacing: 2.5px;
      color: var(--gold);
      font-weight: 600;
      margin-bottom: 16px;
    }
    .section-title {
      font-size: 2.5rem;
      font-weight: 600;
      color: var(--teal);
      line-height: 1.2;
      margin-bottom: 20px;
    }
    .section-subtitle {
      font-size: 1.1rem;
      color: var(--gray-dark);
      max-width: 640px;
      line-height: 1.7;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 32px;
      font-size: 0.9rem;
      font-weight: 600;
      border: 2px solid transparent;
      cursor: pointer;
      transition: all 0.3s ease;
      font-family: 'Inter', sans-serif;
      letter-spacing: 0.3px;
    }
    .btn-primary {
      background: var(--gold);
      color: var(--teal);
      border-color: var(--gold);
    }
    .btn-primary:hover { background: #b8953a; border-color: #b8953a; }
    .btn-outline {
      background: transparent;
      color: var(--white);
      border-color: var(--white);
    }
    .btn-outline:hover { background: var(--white); color: var(--teal); }
    .btn-outline-dark {
      background: transparent;
      color: var(--teal);
      border-color: var(--teal);
    }
    .btn-outline-dark:hover { background: var(--teal); color: var(--white); }
    .btn-text {
      background: none;
      border: none;
      color: var(--gold);
      padding: 0;
      gap: 6px;
    }
    .btn-text::after { content: '→'; transition: transform 0.3s; }
    .btn-text:hover::after { transform: translateX(4px); }

    /* === Header === */
    .header {
      position: fixed;
      top: 0; left: 0; right: 0;
      background: var(--white);
      z-index: 1000;
      border-bottom: 1px solid rgba(0,0,0,0.06);
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 40px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Playfair Display', serif;
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--green);
    }
    .logo-icon {
      width: 36px; height: 36px;
      background: var(--green);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gold);
      font-family: 'Playfair Display', serif;
      font-size: 1.3rem;
      font-weight: 700;
    }
    .main-nav { display: flex; align-items: center; gap: 4px; }
    .nav-link {
      padding: 8px 16px;
      font-size: 0.85rem;
      font-weight: 500;
      color: var(--teal);
      border-radius: 4px;
      transition: all 0.2s;
      cursor: pointer;
      position: relative;
    }
    .nav-link:hover, .nav-link.active { color: var(--green); background: rgba(0,63,45,0.04); }
    .nav-link.has-mega::after {
      content: '';
      display: inline-block;
      width: 6px; height: 6px;
      border-right: 1.5px solid currentColor;
      border-bottom: 1.5px solid currentColor;
      transform: rotate(45deg);
      margin-left: 6px;
      margin-bottom: 2px;
    }
    .header-actions { display: flex; align-items: center; gap: 12px; }
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }
    .hamburger span {
      display: block;
      width: 24px; height: 2px;
      background: var(--teal);
      transition: all 0.3s;
    }

    /* === Mega Menu === */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 0; right: 0;
      background: var(--white);
      border-top: 1px solid rgba(0,0,0,0.06);
      box-shadow: 0 20px 40px rgba(0,0,0,0.12);
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: all 0.3s ease;
      padding: 48px 0;
      z-index: 999;
    }
    .nav-item:hover .mega-menu,
    .mega-menu.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .mega-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 40px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
    }
    .mega-col h3 {
      font-size: 0.7rem;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--gray-mid);
      margin-bottom: 20px;
      font-family: 'Inter', sans-serif;
      font-weight: 600;
    }
    .mega-col ul { display: flex; flex-direction: column; gap: 4px; }
    .mega-col ul a {
      display: block;
      padding: 10px 12px;
      font-size: 0.9rem;
      color: var(--teal);
      border-radius: 4px;
      transition: all 0.2s;
    }
    .mega-col ul a:hover { background: rgba(0,63,45,0.05); color: var(--green); }

    /* === Mobile Nav === */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 72px;
      left: 0; right: 0; bottom: 0;
      background: var(--white);
      z-index: 999;
      overflow-y: auto;
      padding: 24px 24px 48px;
    }
    .mobile-nav.open { display: block; }
    .mobile-nav-item {
      border-bottom: 1px solid rgba(0,0,0,0.06);
    }
    .mobile-nav-toggle {
      display: flex;
      justify-content: space-between;
      align-items: center;
      width: 100%;
      padding: 16px 0;
      background: none;
      border: none;
      font-size: 0.95rem;
      font-weight: 500;
      color: var(--teal);
      cursor: pointer;
      font-family: 'Inter', sans-serif;
    }
    .mobile-nav-toggle .arrow {
      width: 18px; height: 18px;
      position: relative;
      transition: transform 0.3s;
    }
    .mobile-nav-toggle .arrow::before,
    .mobile-nav-toggle .arrow::after {
      content: '';
      position: absolute;
      background: var(--gray-mid);
      transition: all 0.3s;
    }
    .mobile-nav-toggle .arrow::before {
      width: 10px; height: 1.5px;
      top: 9px; left: 4px;
    }
    .mobile-nav-toggle .arrow::after {
      width: 1.5px; height: 10px;
      top: 4px; left: 9px;
    }
    .mobile-nav-item.open .mobile-nav-toggle .arrow { transform: rotate(45deg); }
    .mobile-subnav {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease;
    }
    .mobile-nav-item.open .mobile-subnav { max-height: 500px; }
    .mobile-subnav a {
      display: block;
      padding: 10px 24px;
      font-size: 0.88rem;
      color: var(--gray-dark);
    }
    .mobile-subnav a:hover { color: var(--green); background: rgba(0,63,45,0.03); }
    .mobile-subnav .sub-label {
      font-size: 0.65rem;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--gray-mid);
      padding: 16px 24px 8px;
      font-weight: 600;
    }

    /* === Hero === */
    .hero {
      margin-top: 72px;
      position: relative;
      min-height: 580px;
      display: flex;
      align-items: center;
      background: linear-gradient(135deg, var(--green) 0%, var(--teal) 100%);
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 600"><rect width="800" height="600" fill="none"/><polygon points="400,0 800,200 800,600 400,600" fill="rgba(255,255,255,0.03)"/><polygon points="0,100 300,0 300,600 0,600" fill="rgba(255,255,255,0.02)"/></svg>') center/cover;
      opacity: 0.5;
    }
    .hero .container { position: relative; z-index: 1; }
    .hero-content { max-width: 680px; }
    .hero-tag {
      display: inline-block;
      font-size: 0.7rem;
      text-transform: uppercase;
      letter-spacing: 2.5px;
      color: var(--gold);
      font-weight: 600;
      margin-bottom: 20px;
      border: 1px solid rgba(200,168,78,0.3);
      padding: 6px 16px;
      border-radius: 2px;
    }
    .hero h1 {
      font-size: 3.5rem;
      font-weight: 700;
      color: var(--white);
      line-height: 1.15;
      margin-bottom: 24px;
    }
    .hero p {
      font-size: 1.15rem;
      color: rgba(255,255,255,0.85);
      line-height: 1.7;
      margin-bottom: 36px;
      max-width: 540px;
    }
    .hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }
    .hero-image-area {
      position: absolute;
      right: 0; top: 0; bottom: 0;
      width: 42%;
      background: linear-gradient(90deg, var(--green) 0%, transparent 100%),
        url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 600"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 40" fill="none" stroke="rgba(255,255,255,0.06)" stroke-width="0.5"/></pattern></defs><rect width="600" height="600" fill="%23002d1f"/><rect width="600" height="600" fill="url(%23grid)"/><rect x="80" y="80" width="300" height="200" fill="rgba(255,255,255,0.03)" rx="4"/><rect x="100" y="100" width="300" height="200" fill="rgba(255,255,255,0.04)" rx="4"/><rect x="120" y="120" width="280" height="180" fill="rgba(255,255,255,0.03)" rx="4"/><rect x="140" y="300" width="320" height="220" fill="rgba(255,255,255,0.04)" rx="4"/><rect x="160" y="320" width="320" height="220" fill="rgba(255,255,255,0.03)" rx="4"/></svg>') center/cover;
    }

    /* === Featured Insights === */
    .insights-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
    }
    .insight-card {
      background: var(--white);
      border: 1px solid rgba(0,0,0,0.08);
      border-radius: 4px;
      overflow: hidden;
      transition: all 0.3s;
    }
    .insight-card:hover {
      box-shadow: 0 8px 30px rgba(0,0,0,0.08);
      transform: translateY(-2px);
    }
    .insight-card-image {
      height: 200px;
      background: linear-gradient(135deg, #e8e8e8 0%, #d5d5d5 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-mid);
      font-size: 0.8rem;
    }
    .insight-card:nth-child(1) .insight-card-image { background: linear-gradient(135deg, #003F2D 0%, #012A2D 100%); }
    .insight-card:nth-child(2) .insight-card-image { background: linear-gradient(135deg, #3a5a40 0%, #2d4a38 100%); }
    .insight-card:nth-child(3) .insight-card-image { background: linear-gradient(135deg, #4a6a50 0%, #3d5a45 100%); }
    .insight-card-body { padding: 24px; }
    .insight-category {
      font-size: 0.7rem;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--gold);
      font-weight: 600;
      margin-bottom: 10px;
    }
    .insight-card h3 {
      font-size: 1.15rem;
      font-weight: 600;
      color: var(--teal);
      line-height: 1.4;
    }

    /* === Announcement Banner === */
    .announcement {
      background: linear-gradient(135deg, var(--green) 0%, var(--teal) 100%);
      padding: 32px 0;
    }
    .announcement-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 20px;
    }
    .announcement-tag {
      font-size: 0.65rem;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--gold);
      font-weight: 600;
      border: 1px solid rgba(200,168,78,0.4);
      padding: 4px 12px;
      border-radius: 2px;
    }
    .announcement-text {
      font-size: 1.15rem;
      color: var(--white);
      font-weight: 400;
      flex: 1;
      margin-left: 20px;
    }

    /* === About Statement === */
    .about-statement {
      background: var(--off-white);
      text-align: center;
    }
    .about-statement .section-title { max-width: 850px; margin: 0 auto 24px; }
    .about-statement .section-subtitle { max-width: 750px; margin: 0 auto 32px; }

    /* === What We Do Tabs === */
    .what-we-do { background: var(--white); }
    .tabs-container {
      display: grid;
      grid-template-columns: 320px 1fr;
      gap: 60px;
      margin-top: 48px;
    }
    .tabs-nav { display: flex; flex-direction: column; gap: 2px; }
    .tab-btn {
      text-align: left;
      padding: 20px 24px;
      background: none;
      border: none;
      border-left: 3px solid transparent;
      cursor: pointer;
      font-family: 'Inter', sans-serif;
      transition: all 0.3s;
      color: var(--gray-dark);
      font-size: 0.95rem;
    }
    .tab-btn:hover { background: var(--off-white); color: var(--teal); }
    .tab-btn.active {
      background: rgba(0,63,45,0.04);
      border-left-color: var(--gold);
      color: var(--teal);
      font-weight: 600;
    }
    .tab-panel { display: none; }
    .tab-panel.active { display: block; }
    .tab-panel h3 {
      font-size: 2rem;
      font-weight: 600;
      color: var(--teal);
      margin-bottom: 20px;
    }
    .tab-panel p {
      font-size: 1.05rem;
      color: var(--gray-dark);
      line-height: 1.7;
      margin-bottom: 28px;
      max-width: 580px;
    }
    .tab-stats {
      display: flex;
      gap: 40px;
      margin-bottom: 28px;
      flex-wrap: wrap;
    }
    .tab-stat {
      font-size: 2rem;
      font-weight: 700;
      color: var(--green);
      line-height: 1;
    }
    .tab-stat span {
      display: block;
      font-size: 0.75rem;
      font-weight: 500;
      color: var(--gray-mid);
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-top: 4px;
    }

    /* === Newsletter === */
    .newsletter {
      background: linear-gradient(135deg, var(--teal) 0%, var(--green) 100%);
      text-align: center;
    }
    .newsletter .section-label { color: var(--gold); }
    .newsletter .section-title { color: var(--white); }
    .newsletter .section-subtitle { color: rgba(255,255,255,0.8); margin: 0 auto 32px; }
    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 0 auto;
    }
    .newsletter-form input {
      flex: 1;
      padding: 14px 20px;
      border: 1px solid rgba(255,255,255,0.2);
      background: rgba(255,255,255,0.08);
      color: var(--white);
      font-size: 0.9rem;
      font-family: 'Inter', sans-serif;
      border-radius: 2px;
      outline: none;
    }
    .newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
    .newsletter-form input:focus { border-color: var(--gold); }
    .newsletter-form .btn { white-space: nowrap; }

    /* === Latest Insights === */
    .latest-insights { background: var(--off-white); }
    .insights-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      margin-bottom: 40px;
      flex-wrap: wrap;
      gap: 16px;
    }
    .insights-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
    .insight-article {
      background: var(--white);
      border: 1px solid rgba(0,0,0,0.06);
      padding: 32px;
      transition: all 0.3s;
    }
    .insight-article:hover { box-shadow: 0 8px 24px rgba(0,0,0,0.06); }
    .insight-type {
      font-size: 0.65rem;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--gold);
      font-weight: 600;
      margin-bottom: 4px;
    }
    .insight-series {
      font-size: 0.72rem;
      color: var(--gray-mid);
      font-weight: 500;
      margin-bottom: 16px;
    }
    .insight-article h3 {
      font-size: 1.1rem;
      font-weight: 600;
      color: var(--teal);
      line-height: 1.4;
      margin-bottom: 16px;
    }
    .insight-date {
      font-size: 0.8rem;
      color: var(--gray-mid);
    }

    /* === Our Commitment === */
    .commitment-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 28px;
    }
    .commitment-card {
      padding: 36px 28px;
      background: var(--off-white);
      border-radius: 4px;
      text-align: center;
      transition: all 0.3s;
    }
    .commitment-card:hover { background: var(--white); box-shadow: 0 8px 24px rgba(0,0,0,0.06); }
    .commitment-icon {
      width: 56px; height: 56px;
      margin: 0 auto 20px;
      background: rgba(0,63,45,0.06);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.4rem;
      color: var(--green);
    }
    .commitment-card h3 {
      font-size: 1.1rem;
      font-weight: 600;
      color: var(--teal);
      margin-bottom: 12px;
    }
    .commitment-card p {
      font-size: 0.9rem;
      color: var(--gray-dark);
      line-height: 1.6;
      margin-bottom: 20px;
    }

    /* === Footer === */
    .footer {
      background: var(--navy-bg);
      color: rgba(255,255,255,0.7);
      padding: 64px 0 32px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 40px;
      margin-bottom: 48px;
    }
    .footer-brand .logo { color: var(--white); margin-bottom: 16px; }
    .footer-brand p {
      font-size: 0.85rem;
      line-height: 1.7;
      max-width: 300px;
    }
    .footer h4 {
      font-size: 0.7rem;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--white);
      margin-bottom: 20px;
      font-family: 'Inter', sans-serif;
      font-weight: 600;
    }
    .footer-links { display: flex; flex-direction: column; gap: 10px; }
    .footer-links a {
      font-size: 0.85rem;
      color: rgba(255,255,255,0.6);
      transition: color 0.2s;
    }
