  // Mega menu toggle for touch devices and click
  (function() {
    var navItem = document.getElementById('servicesNavItem');
    var megaMenu = document.getElementById('megaMenu');
    var navLink = document.getElementById('servicesNavLink');
    var isTouch = 'ontouchstart' in window;

    if (isTouch) {
      navLink.addEventListener('click', function(e) {
        e.preventDefault();
        megaMenu.classList.toggle('open');
      });
      document.addEventListener('click', function(e) {
        if (!navItem.contains(e.target)) {
          megaMenu.classList.remove('open');
        }
      });
    }
  })();

  // Mobile menu
  (function() {
    var hamburger = document.getElementById('hamburger');
    var mobileNav = document.getElementById('mobileNav');
    hamburger.addEventListener('click', function() {
      mobileNav.classList.toggle('open');
    });

    // Mobile accordion
    var mobileItems = document.querySelectorAll('.mobile-nav-item');
    mobileItems.forEach(function(item) {
      var toggle = item.querySelector('.mobile-nav-toggle');
      if (toggle) {
        toggle.addEventListener('click', function() {
          item.classList.toggle('open');
        });
      }
    });
  })();

  // What We Do tabs
  (function() {
    var tabBtns = document.querySelectorAll('.tab-btn');
    var tabPanels = document.querySelectorAll('.tab-panel');

    tabBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        var target = btn.getAttribute('data-tab');
        tabBtns.forEach(function(b) { b.classList.remove('active'); b.setAttribute('aria-selected', 'false'); });
        btn.classList.add('active');
        btn.setAttribute('aria-selected', 'true');
        tabPanels.forEach(function(p) { p.classList.remove('active'); });
        document.getElementById('panel-' + target).classList.add('active');
      });
    });
  })();

  // Newsletter form
  (function() {
    var form = document.getElementById('newsletterForm');
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      var email = form.querySelector('input').value;
      if (email) {
        alert('Thank you for subscribing to Our Take Newsletter. You will receive a confirmation email shortly.');
        form.reset();
      }
    });
  })();
</script>

