  // Mobile menu
  (function() {
    var hamburger = document.getElementById('hamburger');
    var mobileNav = document.getElementById('mobileNav');
    hamburger.addEventListener('click', function() { mobileNav.classList.toggle('open'); });
    var mobileItems = document.querySelectorAll('.mobile-nav-item');
    mobileItems.forEach(function(item) {
      var toggle = item.querySelector('.mobile-nav-toggle');
      if (toggle) {
        toggle.addEventListener('click', function() { item.classList.toggle('open'); });
      }
    });
  })();

  // Mega menu
  (function() {
    var navItem = document.querySelector('.nav-item');
    var megaMenu = navItem ? navItem.querySelector('.mega-menu') : null;
    var navLink = navItem ? navItem.querySelector('.nav-link') : null;
    var isTouch = 'ontouchstart' in window;
    if (navLink && megaMenu && isTouch) {
      navLink.addEventListener('click', function(e) { e.preventDefault(); megaMenu.classList.toggle('open'); });
      document.addEventListener('click', function(e) { if (!navItem.contains(e.target)) megaMenu.classList.remove('open'); });
    }
  })();

  // Carousel
  (function() {
    var track = document.getElementById('carouselTrack');
    var dots = document.querySelectorAll('.carousel-dot');
    var prevBtn = document.getElementById('carouselPrev');
    var nextBtn = document.getElementById('carouselNext');
    var currentIndex = 0;
    var totalSlides = dots.length;

    function goToSlide(index) {
      currentIndex = index;
      track.style.transform = 'translateX(-' + (currentIndex * 100) + '%)';
      dots.forEach(function(d, i) { d.classList.toggle('active', i === currentIndex); });
    }

    prevBtn.addEventListener('click', function() {
      goToSlide((currentIndex - 1 + totalSlides) % totalSlides);
    });
    nextBtn.addEventListener('click', function() {
      goToSlide((currentIndex + 1) % totalSlides);
    });
    dots.forEach(function(dot) {
      dot.addEventListener('click', function() {
        goToSlide(parseInt(this.getAttribute('data-index')));
      });
    });
  })();
</script>

